import requests, bs4, re
xml=requests.get('https://www.ncbi.nlm.nih.gov/research/bionlp/RESTful/pmcoa.cgi/BioC_json/PMC4959582/unicode').json()
text=' '.join(p['text'] for d in xml for p in d.get('passages',[]) if p.get('text'))
for pat in ['AG490','tumor growth','tumor volume','HepG2','Fas','FasL','BAX','perforin','granzyme','G1 phase','apoptosis','in vivo']:
 print('\n###',pat)
 for m in list(re.finditer(pat,text,re.I))[:8]: print(text[max(0,m.start()-220):m.end()+420].replace('\n',' '))
